#!/bin/sh
# Lints the repository: Perl formatting and style, workflow files, and leaked
# secrets. CI runs the same script.
#
#   author/lint.sh          check
#   author/lint.sh --fix    reformat Perl files in place, then check
set -eu

cd "$(dirname "$0")/.."

# Perl sources, tracked or new (not ignored), minus files generated by Minilla.
perl_files() {
    git ls-files --cached --others --exclude-standard '*.pm' '*.pl' '*.t' | grep -v '^Build\.PL$'
}

status=0

if [ "${1:-}" = "--fix" ]; then
    perl_files | xargs perltidy --profile=.perltidyrc --backup-and-modify-in-place --backup-file-extension=/
fi

echo '== perltidy'
for file in $(perl_files); do
    perltidy --profile=.perltidyrc --assert-tidy --standard-error-output --standard-output "$file" >/dev/null \
        || status=1
done

echo '== perlcritic'
perlcritic --profile xt/perlcriticrc lib builder || status=1

echo '== test PTX version'
# CUDA 12.0 drivers JIT-compile PTX ISA 8.0 at most; newer nvcc emits newer
# headers for the same instructions.
for file in t/ptx/*.ptx; do
    version=$(sed -n 's/^\.version //p' "$file")
    if [ "$version" != "8.0" ]; then
        echo "$file: .version $version (expected 8.0 for CUDA 12.0 drivers)"
        status=1
    fi
done

echo '== English only'
# The repository is written in English; flag Japanese text in tracked files.
# Perl decodes the files as UTF-8 itself, so the locale does not matter.
git ls-files -z --cached --others --exclude-standard | xargs -0 perl -CSD -nle '
    if (/[\p{Han}\p{Hiragana}\p{Katakana}]/) { print "$ARGV: Japanese text"; $found = 1; close ARGV }
    END { exit($found ? 1 : 0) }
' || status=1

echo '== actionlint'
actionlint || status=1

echo '== gitleaks (working tree and history)'
gitleaks dir --no-banner --redact . || status=1
gitleaks git --no-banner --redact . || status=1

exit "$status"
